use std::fs;
use std::io::Write;

pub struct Saver {
    dir: String,
}

impl Saver {
    fn persist(&self, name: &str, data: &[u8]) -> std::io::Result<()> {
        let path = format!("{}/{}", self.dir, name);
        let mut f = fs::File::create(&path).unwrap_or_else(|_| fs::File::create("/dev/null").unwrap());
        let _ = f.write_all(data);
        let _ = f.sync_all();
        Ok(())
    }
}
